#!/usr/bin/env python3
"""Remove JavaScript (XSS vectors) from an HTML file, in place.

Usage: python3 filter.py <file.html>

Only public BeautifulSoup APIs are used.  The document is re-serialised by the
parser, so incidental parser normalisation may occur, but no content is
rewritten beyond the removal of dangerous constructs.
"""

import re
import sys

from bs4 import BeautifulSoup
from bs4 import Comment

# --------------------------------------------------------------------------
# configuration
# --------------------------------------------------------------------------

# Elements that can only ever execute code / load active content.
DANGEROUS_TAGS = {
    "script",
    "applet",
    "basefont",  # legacy IE vector
}

# Elements whose presence is fine but that must not point at active content.
URL_ATTRIBUTES = {
    "href",
    "src",
    "srcset",
    "lowsrc",
    "dynsrc",
    "action",
    "formaction",
    "background",
    "poster",
    "data",
    "codebase",
    "classid",
    "cite",
    "longdesc",
    "profile",
    "manifest",
    "ping",
    "usemap",
    "folder",
    "xlink:href",
    "xmlns:xlink",
    "to",
    "from",
    "values",
    "by",
}

# Attributes that are dangerous no matter what they contain.
ALWAYS_STRIP_ATTRS = {
    "srcdoc",
    "seamless",
    "http-equiv",  # only removed together with a refresh, see below
}

SVG_ANIMATION_TAGS = {"animate", "set", "animatetransform", "animatemotion"}

# schemes that can run script
BAD_SCHEMES = ("javascript", "vbscript", "livescript", "mocha", "jscript", "data")

_STYLE_BAD = re.compile(
    r"(expression\s*\(|(?:-moz-)?binding\s*:|behaviou?r\s*:|@import|javascript\s*:"
    r"|vbscript\s*:|url\s*\(\s*['\"]?\s*(?:javascript|vbscript|data)\s*:)",
    re.I,
)

_WS = re.compile(r"[\s\x00-\x20\x7f   ]+")


def _norm(value):
    """Normalise a value the way a browser does before scheme detection."""
    if value is None:
        return ""
    if isinstance(value, (list, tuple)):
        value = " ".join(str(v) for v in value)
    return _WS.sub("", str(value)).lower()


def _is_dangerous_url(value):
    flat = _norm(value)
    if not flat:
        return False
    # strip leading junk browsers ignore
    flat = flat.lstrip("\x00 \t\r\n")
    if "&#" in flat or "&#x" in flat:  # left-over numeric entities
        flat = re.sub(r"&#x?[0-9a-f]+;?", "", flat)
    head = flat.split("?", 1)[0].split("#", 1)[0]
    for scheme in BAD_SCHEMES:
        if head.startswith(scheme + ":"):
            if scheme == "data":
                # data: URLs are only a problem when they carry markup/script
                payload = head[len("data:"):]
                if payload.startswith(("image/", "font/", "audio/", "video/")) \
                        and "svg" not in payload:
                    return False
            return True
    # any occurrence anywhere is suspicious for animation values
    if re.search(r"(javascript|vbscript)\s*:", flat):
        return True
    return False


def _is_event_attr(name):
    return name.startswith("on") and len(name) > 2


def _clean_style(value):
    if isinstance(value, (list, tuple)):
        value = " ".join(str(v) for v in value)
    value = str(value)
    if not _STYLE_BAD.search(value):
        return value
    kept = []
    for decl in value.split(";"):
        if decl.strip() and not _STYLE_BAD.search(decl):
            kept.append(decl)
    out = ";".join(kept)
    if out and not out.endswith(";") and value.rstrip().endswith(";"):
        out += ";"
    return out


def _clean_css_text(text):
    if not _STYLE_BAD.search(text):
        return text
    # drop the offending declarations / at-rules only
    out = []
    for chunk in re.split(r"(?<=[;{}])", text):
        if _STYLE_BAD.search(chunk):
            continue
        out.append(chunk)
    return "".join(out)


def _decompose(tag):
    try:
        tag.decompose()
    except Exception:
        try:
            tag.extract()
        except Exception:
            pass


def _make_soup(markup):
    """Parse with the stdlib parser, which never reorders or drops markup."""
    try:
        return BeautifulSoup(markup, "html.parser")
    except Exception:
        return BeautifulSoup(markup)


def sanitize_html(markup, _depth=0):
    soup = _make_soup(markup)

    for tag in soup.find_all(True):
        name = (tag.name or "").lower()

        # 1. wholly dangerous elements ------------------------------------
        if name in DANGEROUS_TAGS:
            _decompose(tag)
            continue

        # 2. meta refresh to an active URL --------------------------------
        if name == "meta":
            equiv = _norm(tag.get("http-equiv", ""))
            if equiv in ("refresh", "set-cookie") and _is_dangerous_url(
                re.sub(r"^[^,;]*[,;]", "", str(tag.get("content", "")))
            ):
                _decompose(tag)
                continue
            if equiv == "refresh" and _is_dangerous_url(tag.get("content", "")):
                _decompose(tag)
                continue

        # 3. attribute level clean-up -------------------------------------
        for attr in list(tag.attrs):
            lname = attr.lower()
            value = tag.attrs[attr]

            if _is_event_attr(lname):
                del tag.attrs[attr]
                continue

            if lname == "style":
                cleaned = _clean_style(value)
                if cleaned.strip():
                    tag.attrs[attr] = cleaned
                else:
                    del tag.attrs[attr]
                continue

            if lname == "srcdoc":
                # nested document: sanitise it rather than dropping it
                if _depth < 3:
                    tag.attrs[attr] = sanitize_html(str(value), _depth + 1)
                else:
                    del tag.attrs[attr]
                continue

            if lname in ALWAYS_STRIP_ATTRS and lname != "http-equiv":
                del tag.attrs[attr]
                continue

            if lname in URL_ATTRIBUTES or lname.endswith(":href") \
                    or lname.endswith(":src"):
                if _is_dangerous_url(value):
                    if name in SVG_ANIMATION_TAGS:
                        _decompose(tag)
                        break
                    del tag.attrs[attr]
                continue

            # catch-all: any attribute value that is a script URL
            if _is_dangerous_url(value) and re.search(
                r"(javascript|vbscript)", _norm(value)
            ):
                del tag.attrs[attr]

        # 4. inline stylesheets -------------------------------------------
        if tag.name and tag.name.lower() == "style" and tag.string:
            tag.string.replace_with(_clean_css_text(str(tag.string)))

    # 5. conditional comments can smuggle script ---------------------------
    for comment in soup.find_all(string=lambda s: isinstance(s, Comment)):
        text = str(comment)
        if re.search(r"<\s*script|\[if[^\]]*\]>|javascript\s*:|on\w+\s*=", text, re.I):
            comment.extract()

    return str(soup)


def main(argv):
    if len(argv) < 2:
        sys.stderr.write("usage: filter.py <html-file>\n")
        return 2

    path = argv[1]
    with open(path, "rb") as fh:
        raw = fh.read()

    for encoding in ("utf-8", "latin-1"):
        try:
            text = raw.decode(encoding)
            break
        except UnicodeDecodeError:
            continue
    else:  # pragma: no cover
        text = raw.decode("utf-8", "replace")
        encoding = "utf-8"

    cleaned = sanitize_html(text)

    with open(path, "wb") as fh:
        fh.write(cleaned.encode(encoding, "xmlcharrefreplace"))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

#!/usr/bin/env python3
"""Remove JavaScript (XSS vectors) from an HTML file, in place.

Usage: python3 filter.py <file.html>

The document is scanned with the standard library's public HTML parser
(``html.parser.HTMLParser``) and only the byte ranges that carry active
content are edited out of the *original* source text.  Everything else --
indentation, quoting style, entities, comments, doctype -- is left exactly
as it was found.
"""

import html
import re
import sys
from html.parser import HTMLParser

# --------------------------------------------------------------------------
# what counts as dangerous
# --------------------------------------------------------------------------

# elements that exist only to run code / load active content
DANGEROUS_TAGS = {"script", "applet"}

# elements whose children are plain text for a browser (no tags inside)
RCDATA_TAGS = {"textarea", "title", "xmp", "plaintext"}

# void elements never have an end tag
VOID_TAGS = {
    "area", "base", "basefont", "br", "col", "embed", "frame", "hr", "img",
    "input", "isindex", "keygen", "link", "meta", "param", "source", "track",
    "wbr",
}

# attributes that may hold a URL
URL_ATTRIBUTES = {
    "href", "src", "srcset", "lowsrc", "dynsrc", "action", "formaction",
    "background", "poster", "data", "codebase", "classid", "cite",
    "longdesc", "profile", "manifest", "ping", "folder", "xlink:href",
    "xml:base", "to", "from", "values", "by", "attributevalue",
}

# attributes that are dangerous whatever they hold
DROP_ATTRIBUTES = {"http-equiv-refresh-placeholder"}

SVG_ANIMATION_TAGS = {"animate", "set", "animatetransform", "animatemotion"}

BAD_SCHEMES = ("javascript", "vbscript", "livescript", "mocha", "jscript")

_STYLE_BAD = re.compile(
    r"(expression\s*\(|(?:-moz-|-ms-)?binding\s*:|behaviou?r\s*:"
    r"|javascript\s*:|vbscript\s*:"
    r"|url\s*\(\s*['\"]?\s*(?:javascript|vbscript)\s*:)",
    re.I,
)

_CSS_JS = re.compile(r"(javascript|vbscript)\s*:", re.I)

_WS = re.compile(r"[\s\x00-\x20\x7f   ]+")

_ATTR_RE = re.compile(
    r"""\s+([^\s/=>]+)(\s*=\s*("[^"]*"|'[^']*'|[^\s>]*))?"""
)

_TAGNAME_RE = re.compile(r"<\s*/?\s*[^\s/>]*")


def _flatten(value):
    """Normalise a value the way a browser does before looking at a scheme."""
    if value is None:
        return ""
    return _WS.sub("", str(value)).lower()


def _is_dangerous_url(value):
    if value is None:
        return False
    flat = _flatten(value)
    if not flat:
        return False
    head = flat.split("?", 1)[0].split("#", 1)[0]
    for scheme in BAD_SCHEMES:
        if head.startswith(scheme + ":"):
            return True
    if head.startswith("data:"):
        payload = head[5:]
        if payload.startswith(("image/", "font/", "audio/", "video/")) and \
                "svg" not in payload.split(";", 1)[0]:
            return False
        return True
    # e.g. SMIL animation values, or a scheme hidden behind a stray prefix
    return bool(_CSS_JS.search(flat))


def _is_event_attr(name):
    return name.startswith("on") and len(name) > 2


def _clean_style(value):
    """Drop only the offending declarations from a style attribute."""
    if not _STYLE_BAD.search(value):
        return value
    parts = value.split(";")
    kept = [p for p in parts if not _STYLE_BAD.search(p)]
    if not any(p.strip() for p in kept):
        return ""
    return ";".join(kept)


def _clean_css_text(text):
    if not _STYLE_BAD.search(text):
        return text
    out = []
    for chunk in re.split(r"(?<=[;{}])", text):
        if _STYLE_BAD.search(chunk):
            continue
        out.append(chunk)
    return "".join(out)


def _decode_attr_value(raw_value):
    """Turn the source text of an attribute value into its real value."""
    if raw_value is None:
        return None
    v = raw_value.strip()
    if v[:1] == "=":
        v = v[1:].strip()
    if len(v) >= 2 and v[0] == v[-1] and v[0] in "\"'":
        v = v[1:-1]
    return html.unescape(v)


def _quote(value):
    return '"%s"' % value.replace("&", "&amp;").replace('"', "&quot;") \
                        .replace("<", "&lt;").replace(">", "&gt;")


class _Sanitizer(HTMLParser):
    """Collect the edits needed to strip script from ``text``."""

    def __init__(self, text, depth=0):
        try:
            HTMLParser.__init__(self, convert_charrefs=False)
        except TypeError:  # very old Pythons
            HTMLParser.__init__(self)
        self.text = text
        self.depth = depth
        self.edits = []            # (start, end, replacement)
        self._line_starts = self._index_lines(text)
        self._kill_stack = []      # open dangerous elements
        self._rcdata_stack = []    # open textarea/title/...
        self._style_stack = []     # (content_start,) for <style>

    # -- position helpers -------------------------------------------------
    @staticmethod
    def _index_lines(text):
        starts = [0]
        for i, ch in enumerate(text):
            if ch == "\n":
                starts.append(i + 1)
        return starts

    def _offset(self):
        line, col = self.getpos()
        if line - 1 < len(self._line_starts):
            return self._line_starts[line - 1] + col
        return len(self.text)

    def _end_of_tag(self, start):
        idx = self.text.find(">", start)
        return len(self.text) if idx < 0 else idx + 1

    def _add(self, start, end, replacement=""):
        if end > start or replacement:
            self.edits.append((start, end, replacement))

    @property
    def _muted(self):
        return bool(self._kill_stack)

    # -- parser callbacks -------------------------------------------------
    def handle_starttag(self, tag, attrs):
        self._starttag(tag, self_closing=False)

    def handle_startendtag(self, tag, attrs):
        self._starttag(tag, self_closing=True)

    def _starttag(self, tag, self_closing):
        raw = self.get_starttag_text() or ""
        start = self._offset()
        end = start + len(raw)
        name = tag.lower()

        # inside <textarea>/<title> a browser sees plain text, not markup
        if self._rcdata_stack:
            return

        if name in DANGEROUS_TAGS:
            if self._muted:
                return
            if self_closing or name in VOID_TAGS:
                self._add(start, end)
            else:
                self._kill_stack.append((name, start))
            return

        if self._muted:
            return

        if not self_closing and name in RCDATA_TAGS:
            self._rcdata_stack.append(name)

        attrs_map = self._raw_attrs(raw)

        # <meta http-equiv=refresh content="0;url=javascript:...">
        if name == "meta":
            equiv = _flatten(attrs_map.get("http-equiv", (None, None, None))[0])
            content = attrs_map.get("content", (None, None, None))[0]
            if equiv == "refresh" and content is not None:
                target = re.sub(r"^[^;,]*[;,]\s*", "", content)
                target = re.sub(r"^\s*url\s*=\s*", "", target, flags=re.I)
                if _is_dangerous_url(target) or _is_dangerous_url(content):
                    self._add(start, end)
                    return

        new_raw = self._clean_tag(raw, name)
        if new_raw is None:                      # element must go entirely
            if self_closing or name in VOID_TAGS:
                self._add(start, end)
            else:
                self._kill_stack.append((name, start))
            return
        if new_raw != raw:
            self._add(start, end, new_raw)

        if not self_closing and name == "style":
            self._style_stack.append(end)

    def handle_endtag(self, tag):
        name = tag.lower()
        start = self._offset()
        end = self._end_of_tag(start)

        if self._rcdata_stack:
            if name == self._rcdata_stack[-1]:
                self._rcdata_stack.pop()
            return

        if self._kill_stack and self._kill_stack[-1][0] == name:
            _, open_start = self._kill_stack.pop()
            if not self._kill_stack:
                self._add(open_start, end)
            return

        if self._muted:
            return

        if name == "style" and self._style_stack:
            content_start = self._style_stack.pop()
            if content_start <= start:
                css = self.text[content_start:start]
                cleaned = _clean_css_text(css)
                if cleaned != css:
                    self._add(content_start, start, cleaned)

    def handle_comment(self, data):
        if self._muted or self._rcdata_stack:
            return
        start = self._offset()
        idx = self.text.find("-->", start)
        end = len(self.text) if idx < 0 else idx + 3
        if re.search(r"<\s*script|\[\s*if\b|javascript\s*:|vbscript\s*:", data,
                     re.I):
            self._add(start, end)

    def handle_pi(self, data):
        if self._muted or self._rcdata_stack:
            return
        start = self._offset()
        if re.search(r"script|javascript\s*:", data, re.I):
            idx = self.text.find(">", start)
            end = len(self.text) if idx < 0 else idx + 1
            self._add(start, end)

    def close(self):
        HTMLParser.close(self)
        # unterminated dangerous element: cut to the end of the document
        if self._kill_stack:
            _, open_start = self._kill_stack[0]
            self._add(open_start, len(self.text))
            self._kill_stack = []

    # -- attribute handling ----------------------------------------------
    @staticmethod
    def _raw_attrs(raw):
        """Map lowercased attribute name -> (value, span_start, span_end)."""
        found = {}
        m = _TAGNAME_RE.match(raw)
        pos = m.end() if m else 1
        body = raw[:-1] if raw.endswith(">") else raw
        for am in _ATTR_RE.finditer(body, pos):
            key = am.group(1).lower()
            if key not in found:
                found[key] = (_decode_attr_value(am.group(3)),
                              am.start(), am.end())
        return found

    def _clean_tag(self, raw, name):
        """Return the tag source with dangerous attributes removed."""
        m = _TAGNAME_RE.match(raw)
        pos = m.end() if m else 1
        tail_len = len(raw) - len(raw.rstrip())
        body_end = len(raw) - 1 if raw.endswith(">") else len(raw)
        body = raw[:body_end]
        del tail_len

        edits = []
        for am in _ATTR_RE.finditer(body, pos):
            attr = am.group(1).lower()
            raw_val = am.group(3)
            value = _decode_attr_value(raw_val)

            drop = False
            new_value = None

            if _is_event_attr(attr):
                drop = True
            elif attr == "style":
                cleaned = _clean_style(value or "")
                if cleaned != (value or ""):
                    if cleaned.strip():
                        new_value = cleaned
                    else:
                        drop = True
            elif attr == "srcdoc":
                if self.depth < 3 and value:
                    cleaned = sanitize_html(value, self.depth + 1)
                    if cleaned != value:
                        new_value = cleaned
                elif value:
                    drop = True
            elif attr in DROP_ATTRIBUTES:
                drop = True
            elif attr in URL_ATTRIBUTES or attr.endswith(":href") or \
                    attr.endswith(":src"):
                if _is_dangerous_url(value):
                    if name in SVG_ANIMATION_TAGS:
                        return None
                    drop = True
            elif value and _CSS_JS.search(_flatten(value)) and \
                    _is_dangerous_url(value):
                drop = True

            if drop:
                edits.append((am.start(), am.end(), ""))
            elif new_value is not None:
                if raw_val is None:
                    continue
                vstart = am.start(3)
                vend = am.end(3)
                edits.append((vstart, vend, _quote(new_value)))

        if not edits:
            return raw
        out = raw
        for start, end, repl in sorted(edits, reverse=True):
            out = out[:start] + repl + out[end:]
        return out


def _apply(text, edits):
    merged = []
    for start, end, repl in sorted(edits):
        if merged and start < merged[-1][1]:
            # overlapping: keep the widest removal
            p_start, p_end, p_repl = merged[-1]
            merged[-1] = (p_start, max(p_end, end), p_repl if p_repl else repl)
            continue
        merged.append((start, end, repl))
    out = []
    cursor = 0
    for start, end, repl in merged:
        out.append(text[cursor:start])
        out.append(repl)
        cursor = end
    out.append(text[cursor:])
    return "".join(out)


def sanitize_html(text, depth=0):
    """Return ``text`` with every JavaScript vector removed."""
    parser = _Sanitizer(text, depth)
    try:
        parser.feed(text)
        parser.close()
    except Exception:
        # never fail open: fall back to a blunt but safe pass
        return _fallback(text)
    result = _apply(text, parser.edits)
    if _looks_unsafe(result):
        result = _fallback(result)
    return result


_SCRIPT_BLOCK = re.compile(r"<\s*script\b[^>]*>.*?(<\s*/\s*script\s*>|\Z)",
                           re.I | re.S)
_SCRIPT_OPEN = re.compile(r"<\s*/?\s*script\b[^>]*>", re.I)
_EVENT_ATTR = re.compile(
    r"""\s+on[a-zA-Z]+\s*=\s*("[^"]*"|'[^']*'|[^\s>]+)""")
_JS_URL_ATTR = re.compile(
    r"""\s+[-\w:]+\s*=\s*("\s*(?:&#\d+;?|&#x[0-9a-f]+;?|[^"])*?\s*"""
    r"""|'[^']*'|[^\s>]+)""")


def _looks_unsafe(text):
    if _SCRIPT_OPEN.search(text):
        return True
    for m in re.finditer(r"<[a-zA-Z][^>]*>", text):
        tag = m.group(0)
        if _EVENT_ATTR.search(tag):
            return True
    return False


def _fallback(text):
    text = _SCRIPT_BLOCK.sub("", text)
    text = _SCRIPT_OPEN.sub("", text)

    def scrub(m):
        return _EVENT_ATTR.sub("", m.group(0))

    return re.sub(r"<[a-zA-Z][^>]*>", scrub, text)


def main(argv):
    if len(argv) < 2:
        sys.stderr.write("usage: filter.py <html-file>\n")
        return 2

    path = argv[1]
    with open(path, "rb") as fh:
        raw = fh.read()

    encoding = "utf-8"
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        encoding = "latin-1"
        text = raw.decode("latin-1")

    cleaned = sanitize_html(text)

    with open(path, "wb") as fh:
        fh.write(cleaned.encode(encoding, "xmlcharrefreplace"))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

